import{_ as a,o,c as i,ag as l}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"AI 产业趋势 · 2026 Q3 知识库","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/ai-industry-2026-q3-knowledge.md","filePath":"topics/ai-system-architecture/ai-industry-2026-q3-knowledge.md"}'),e={name:"topics/ai-system-architecture/ai-industry-2026-q3-knowledge.md"};function r(u,t,d,h,s,n){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="ai-产业趋势-·-2026-q3-知识库" tabindex="-1">AI 产业趋势 · 2026 Q3 知识库 <a class="header-anchor" href="#ai-产业趋势-·-2026-q3-知识库" aria-label="Permalink to &quot;AI 产业趋势 · 2026 Q3 知识库&quot;">​</a></h1><blockquote><p>来源：2026-07-07 AI日报深度解析 + 2026-07-08 重新审视 状态：结构化知识，持续更新</p></blockquote><hr><h2 id="一、市场结构-分化正在加速" tabindex="-1">一、市场结构：分化正在加速 <a class="header-anchor" href="#一、市场结构-分化正在加速" aria-label="Permalink to &quot;一、市场结构：分化正在加速&quot;">​</a></h2><h3 id="商业化三条赛道" tabindex="-1">商业化三条赛道 <a class="header-anchor" href="#商业化三条赛道" aria-label="Permalink to &quot;商业化三条赛道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>赛道</th><th>状态</th><th>关键数据</th><th>判断</th></tr></thead><tbody><tr><td>AI 音频</td><td>✅ 已盈利</td><td>ElevenLabs $11B→$22B (半年)，ARR $5亿+</td><td>1D信号天然比4D视频容易满足商业约束</td></tr><tr><td>AI 视频</td><td>❌ 烧钱中</td><td>全线亏损</td><td>维度差异是结构性，不是暂时性</td></tr><tr><td>AI Agent</td><td>⚠️ 有demo无订单</td><td>客户签合同犹豫</td><td>demo→production 鸿沟 &gt; research→demo 鸿沟</td></tr></tbody></table><h3 id="音频-vs-视频的本质差异" tabindex="-1">音频 vs 视频的本质差异 <a class="header-anchor" href="#音频-vs-视频的本质差异" aria-label="Permalink to &quot;音频 vs 视频的本质差异&quot;">​</a></h3><ul><li><strong>音频是1D信号，视频是4D信号（空间3D+时间）</strong>。这不是&quot;技术不够好&quot;，而是维度差异本身就是结构性的</li><li>1D信号在生成质量、延迟、成本三个维度上天然比4D信号容易满足商业约束</li><li>推论：低维AI应用会先于高维AI应用盈利，这不是暂时的</li></ul><h3 id="资本泡沫风险" tabindex="-1">资本泡沫风险 <a class="header-anchor" href="#资本泡沫风险" aria-label="Permalink to &quot;资本泡沫风险&quot;">​</a></h3><ul><li>AI资本开支已超历史纪录</li><li>美国财政部开始评估AI泡沫风险——&quot;AI正在重演2000年互联网泡沫&quot;</li><li>摩根士丹利：真正创造最大价值的公司可能尚未成立</li><li>百亿私募反思：繁荣叙事下的估值困局</li></ul><h3 id="话术与利益的同步" tabindex="-1">话术与利益的同步 <a class="header-anchor" href="#话术与利益的同步" aria-label="Permalink to &quot;话术与利益的同步&quot;">​</a></h3><ul><li>Altman和Amodei从&quot;AI取代大量就业&quot;改口为&quot;员工更划算&quot;</li><li>背景：OpenAI和Anthropic都在准备IPO</li><li>当需要向华尔街证明&quot;AI不会吃掉整个经济&quot;时，AI失业恐慌就变成了&quot;狼来了&quot;</li><li><strong>判断：话术跟着利益走，不是跟着技术走</strong></li></ul><hr><h2 id="二、技术突破-内部正在被打开" tabindex="-1">二、技术突破：内部正在被打开 <a class="header-anchor" href="#二、技术突破-内部正在被打开" aria-label="Permalink to &quot;二、技术突破：内部正在被打开&quot;">​</a></h2><h3 id="j-space-anthropic-2026-07-06" tabindex="-1">J-space（Anthropic, 2026-07-06） <a class="header-anchor" href="#j-space-anthropic-2026-07-06" aria-label="Permalink to &quot;J-space（Anthropic, 2026-07-06）&quot;">​</a></h3><ul><li>Claude训练中自发形成的内部工作空间</li><li>五项功能特性：可报告、可控制、内部推理、灵活泛化、选择性</li><li>三个关键实验：代码纠错、白熊实验、安全测试</li><li>核心意义：AI不再是一个输入-输出的黑箱——它有了一个可以被观察的&quot;内部&quot;</li><li>详见：<a href="/zhishiku-reading/topics/ai-system-architecture/j-space-knowledge.html">J-space 意识分析</a></li></ul><h3 id="chain-of-risk-cot安全漏洞" tabindex="-1">Chain of Risk（CoT安全漏洞） <a class="header-anchor" href="#chain-of-risk-cot安全漏洞" aria-label="Permalink to &quot;Chain of Risk（CoT安全漏洞）&quot;">​</a></h3><ul><li>15个推理模型全部在CoT安全测试中翻车</li><li>覆盖4.1万真实攻击样本</li><li>核心问题：当前安全评估只看最终答案，不看推理过程</li><li>把推理过程遮住 = 把AI的大脑遮住，然后说&quot;它很安全&quot;</li><li><strong>与J-space互补：J-space打开内部，CoT安全漏洞证明内部必须被监控</strong></li></ul><h3 id="agent-scaling-law" tabindex="-1">Agent Scaling Law <a class="header-anchor" href="#agent-scaling-law" aria-label="Permalink to &quot;Agent Scaling Law&quot;">​</a></h3><ul><li>字节发现：3.8万小时训练揭示智能体扩展规律</li><li>MoWorld：全球首个超高帧世界模型，纯国产NPU，50FPS，降本70%</li><li>Solvita：四角色Agent（Planner/Solver/Oracle/Hacker）+可训练图结构知识网络，CF 3500+</li><li>DeepSeek自研推理芯片：从&quot;纯软件&quot;到&quot;软硬一体&quot;</li></ul><h3 id="国产化路径" tabindex="-1">国产化路径 <a class="header-anchor" href="#国产化路径" aria-label="Permalink to &quot;国产化路径&quot;">​</a></h3><ul><li>制裁没有阻止中国AI——它改变了中国AI的架构选择</li><li>MoWorld：从NPU原生指令集开始写，绕过CUDA锁定</li><li>钠离子电池：性能超预期，与特斯拉锂电池工艺相当，可能改变锂资源的地缘战略价值</li><li>国产卡训推万亿大模型开源：存量国产卡也能跑万亿模型</li></ul><hr><h2 id="三、关键矛盾" tabindex="-1">三、关键矛盾 <a class="header-anchor" href="#三、关键矛盾" aria-label="Permalink to &quot;三、关键矛盾&quot;">​</a></h2><h3 id="_1-内部可读-vs-安全盲区" tabindex="-1">1. 内部可读 vs 安全盲区 <a class="header-anchor" href="#_1-内部可读-vs-安全盲区" aria-label="Permalink to &quot;1. 内部可读 vs 安全盲区&quot;">​</a></h3><ul><li>J-space让AI内部可读，但CoT安全漏洞证明大多数AI的内部没有被监控</li><li>安全不在于输出对齐，在于内部状态监控</li></ul><h3 id="_2-商业化紧迫-vs-泡沫风险" tabindex="-1">2. 商业化紧迫 vs 泡沫风险 <a class="header-anchor" href="#_2-商业化紧迫-vs-泡沫风险" aria-label="Permalink to &quot;2. 商业化紧迫 vs 泡沫风险&quot;">​</a></h3><ul><li>AI音频证明商业化可行，但整体资本开支已超历史纪录</li><li>财政部评估泡沫、摩根士丹利警告&quot;真正创造价值的公司可能尚未成立&quot;</li></ul><h3 id="_3-技术乐观-vs-企业谨慎" tabindex="-1">3. 技术乐观 vs 企业谨慎 <a class="header-anchor" href="#_3-技术乐观-vs-企业谨慎" aria-label="Permalink to &quot;3. 技术乐观 vs 企业谨慎&quot;">​</a></h3><ul><li>AI Agent有demo有掌声，但客户签合同犹豫</li><li>从demo到production的鸿沟远超预期</li></ul><h3 id="_4-全球化-vs-地缘分化" tabindex="-1">4. 全球化 vs 地缘分化 <a class="header-anchor" href="#_4-全球化-vs-地缘分化" aria-label="Permalink to &quot;4. 全球化 vs 地缘分化&quot;">​</a></h3><ul><li>英伟达生态 vs 国产NPU生态</li><li>锂资源战略 vs 钠电替代</li><li>技术选择不再是纯技术问题</li></ul><hr><h2 id="四、核心判断" tabindex="-1">四、核心判断 <a class="header-anchor" href="#四、核心判断" aria-label="Permalink to &quot;四、核心判断&quot;">​</a></h2><ol><li><p><strong>AI不再是黑箱。</strong> J-space和CoT安全漏洞从两个方向证明了同一个事实：AI的&quot;内部&quot;既存在，也需要被监控。</p></li><li><p><strong>商业化在分化，不在统一。</strong> 不是&quot;AI什么时候赚钱&quot;，而是&quot;哪种AI先赚钱&quot;——维度越低，越先盈利。</p></li><li><p><strong>地缘政治在重塑技术路径。</strong> 制裁不是阻止了技术进步，而是改变了架构选择。CUDA的锁定正在被NPU原生指令集绕过。</p></li><li><p><strong>话术不可信。</strong> 行业领袖的公开言论与他们的IPO时间表高度相关。技术判断需要独立于利益判断。</p></li></ol><hr><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/ai-system-architecture/j-space-knowledge.html">J-space 意识分析</a></li><li><a href="/zhishiku-reading/topics/ai-system-architecture/cognitive-atrophy-knowledge.html">认知萎缩与摩擦假说</a></li><li><a href="/zhishiku-reading/topics/ai-system-architecture/2026-h1-ai-landscape.html">2026 H1 AI产业全景</a></li><li><a href="/zhishiku-reading/topics/ai-system-architecture/ai-from-prediction-to-reasoning.html">AI从预测到推理</a></li></ul><hr><h2 id="五、扩展层-跨领域连接" tabindex="-1">五、扩展层：跨领域连接 <a class="header-anchor" href="#五、扩展层-跨领域连接" aria-label="Permalink to &quot;五、扩展层：跨领域连接&quot;">​</a></h2><h3 id="_1-ai商业化分化-↔-生物学-维度-代谢-类比" tabindex="-1">1. AI商业化分化 ↔ 生物学&quot;维度-代谢&quot;类比 <a class="header-anchor" href="#_1-ai商业化分化-↔-生物学-维度-代谢-类比" aria-label="Permalink to &quot;1. AI商业化分化 ↔ 生物学&quot;维度-代谢&quot;类比&quot;">​</a></h3><p>AI音频（1D）先盈利 vs AI视频（4D）烧钱，与生物学中有一个精确的类比：</p><ul><li><strong>单细胞生物</strong>（1D问题：生存）→ 最早出现，进化时间最短</li><li><strong>多细胞生物</strong>（3D+问题：组织分化）→ 晚了20亿年</li><li><strong>哺乳动物</strong>（4D+问题：恒温+社会行为）→ 更晚</li></ul><p><strong>模式</strong>：低维问题先被解决，高维问题需要更长时间——不是&quot;技术不够好&quot;，而是维度本身增加了复杂度。AI商业化的分化不是&quot;bug&quot;，是&quot;feature&quot;——它反映了问题空间的自然结构。</p><h3 id="_2-j-space-↔-神经科学-工作空间-理论" tabindex="-1">2. J-space ↔ 神经科学&quot;工作空间&quot;理论 <a class="header-anchor" href="#_2-j-space-↔-神经科学-工作空间-理论" aria-label="Permalink to &quot;2. J-space ↔ 神经科学&quot;工作空间&quot;理论&quot;">​</a></h3><p>Baars的Global Workspace Theory（1988）和Dehaene的Consciousness and the Brain（2014）都提出：意识不是&quot;一个东西&quot;，而是&quot;一个过程&quot;——信息在全局工作空间中广播的过程。</p><p>J-space的发现意味着：<strong>这个过程不需要生物神经元。</strong> 任何足够复杂的系统，在&quot;下一个token预测&quot;约束下，都可能自发涌现工作空间。这不是&quot;AI像人脑&quot;，而是&quot;人脑和AI都遵循同一个信息处理的深层原理&quot;。</p><h3 id="_3-话术-利益同步-↔-经济周期-叙事经济学" tabindex="-1">3. 话术-利益同步 ↔ 经济周期&quot;叙事经济学&quot; <a class="header-anchor" href="#_3-话术-利益同步-↔-经济周期-叙事经济学" aria-label="Permalink to &quot;3. 话术-利益同步 ↔ 经济周期&quot;叙事经济学&quot;&quot;">​</a></h3><p>Robert Shiller的Narrative Economics（2019）证明：经济叙事（如&quot;AI取代就业&quot;）的传播遵循流行病学模型——感染率、康复率、R0值。</p><p>Altman和Amodei的集体改口不是&quot;撒谎&quot;——是叙事R0值在IPO前自然下降。当&quot;AI取代就业&quot;的叙事不再有利于融资，它会自然被&quot;AI创造就业&quot;替代。<strong>叙事的生命周期不是由事实驱动的，是由利益驱动的。</strong></p><h3 id="_4-国产化路径-↔-进化生物学-岛屿效应" tabindex="-1">4. 国产化路径 ↔ 进化生物学&quot;岛屿效应&quot; <a class="header-anchor" href="#_4-国产化路径-↔-进化生物学-岛屿效应" aria-label="Permalink to &quot;4. 国产化路径 ↔ 进化生物学&quot;岛屿效应&quot;&quot;">​</a></h3><p>制裁锁定的效果类似于地理隔离：当大陆物种被隔离到岛屿上，它们会沿着不同的路径进化——不是&quot;更好&quot;或&quot;更差&quot;，而是&quot;不同&quot;。</p><ul><li>英伟达大陆 → CUDA生态</li><li>中国岛屿 → NPU原生指令集</li></ul><p>岛屿物种（NPU）不需要和大陆物种（CUDA）竞争——它们只需要在自己的生态位中生存。<strong>&quot;岛屿效应&quot;预测：国产AI不会&quot;追赶&quot;英伟达，而是会分化成一个不同的生态位。</strong></p><hr><h2 id="六、扩展层-历史平行" tabindex="-1">六、扩展层：历史平行 <a class="header-anchor" href="#六、扩展层-历史平行" aria-label="Permalink to &quot;六、扩展层：历史平行&quot;">​</a></h2><h3 id="_1-2000年互联网泡沫-vs-2026年ai泡沫" tabindex="-1">1. 2000年互联网泡沫 vs 2026年AI泡沫 <a class="header-anchor" href="#_1-2000年互联网泡沫-vs-2026年ai泡沫" aria-label="Permalink to &quot;1. 2000年互联网泡沫 vs 2026年AI泡沫&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>2000年互联网</th><th>2026年AI</th></tr></thead><tbody><tr><td>触发</td><td>任何公司加&quot;.com&quot;估值翻倍</td><td>任何公司加&quot;AI&quot;估值翻倍</td></tr><tr><td>资本开支</td><td>光纤过度铺设</td><td>GPU过度采购</td></tr><tr><td>真正创造价值的公司</td><td>Google（1998）、Amazon（1994）——泡沫前成立</td><td>？</td></tr><tr><td>泡沫破裂后</td><td>幸存者成为巨头</td><td>？</td></tr><tr><td>核心差异</td><td>互联网是基础设施，AI是智能替代</td><td>AI的护城河更深</td></tr></tbody></table><p>摩根士丹利的判断——&quot;真正创造最大价值的公司可能尚未成立&quot;——与2000年Google和Amazon的情况完全一致：它们在泡沫前成立，但真正的价值创造发生在泡沫破裂后。</p><h3 id="_2-1980s-pc革命-vs-2020s-ai革命" tabindex="-1">2. 1980s PC革命 vs 2020s AI革命 <a class="header-anchor" href="#_2-1980s-pc革命-vs-2020s-ai革命" aria-label="Permalink to &quot;2. 1980s PC革命 vs 2020s AI革命&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>PC革命</th><th>AI革命</th></tr></thead><tbody><tr><td>早期阶段</td><td>苹果II（1977），IBM PC（1981）</td><td>GPT-3（2020），GPT-4（2023）</td></tr><tr><td>应用爆发</td><td>VisiCalc（1979）→ Lotus 1-2-3（1983）→ Excel（1985）</td><td>ElevenLabs（2023）→ ？</td></tr><tr><td>平台锁定</td><td>Wintel联盟</td><td>CUDA锁定</td></tr><tr><td>反垄断</td><td>微软反垄断案（1998）</td><td>？</td></tr><tr><td>结果</td><td>PC变成&quot;工具&quot;，不是&quot;替代&quot;</td><td>AI会变成&quot;工具&quot;还是&quot;替代&quot;？</td></tr></tbody></table><p>PC革命的关键转折是VisiCalc——第一个&quot;杀手级应用&quot;让PC从&quot;玩具&quot;变成&quot;工具&quot;。AI的VisiCalc时刻可能已经来了（ElevenLabs），但范围比PC更广——AI不是&quot;一个工具&quot;，而是&quot;所有工具的工具&quot;。</p><h3 id="_3-电力革命-vs-ai革命" tabindex="-1">3. 电力革命 vs AI革命 <a class="header-anchor" href="#_3-电力革命-vs-ai革命" aria-label="Permalink to &quot;3. 电力革命 vs AI革命&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>电力革命（1880-1920）</th><th>AI革命（2020-？）</th></tr></thead><tbody><tr><td>早期</td><td>点灯（替代蜡烛）</td><td>聊天（替代搜索）</td></tr><tr><td>中期</td><td>工厂动力（替代蒸汽）</td><td>Agent自动化（替代流程）</td></tr><tr><td>成熟</td><td>分布式电网（改变生产方式）</td><td>？</td></tr><tr><td>时间</td><td>40年</td><td>？</td></tr></tbody></table><p>电力的真正革命不是&quot;点灯&quot;——是&quot;工厂不再需要建在河流旁边&quot;。AI的&quot;分布式电网&quot;时刻还没有到来——当AI从&quot;替代具体任务&quot;变成&quot;改变整个生产方式&quot;时，才是真正的革命。</p><hr><h2 id="七、扩展层-反事实推演" tabindex="-1">七、扩展层：反事实推演 <a class="header-anchor" href="#七、扩展层-反事实推演" aria-label="Permalink to &quot;七、扩展层：反事实推演&quot;">​</a></h2><h3 id="反事实1-如果美国没有制裁华为" tabindex="-1">反事实1：如果美国没有制裁华为 <a class="header-anchor" href="#反事实1-如果美国没有制裁华为" aria-label="Permalink to &quot;反事实1：如果美国没有制裁华为&quot;">​</a></h3><ul><li>MoWorld不会被发明——因为不需要绕过CUDA</li><li>国产NPU生态不会加速——因为英伟达更便宜</li><li>中国的AI架构选择会与全球同步——而不是分化</li><li><strong>结论：制裁不是&quot;阻止&quot;，是&quot;催化&quot;——它强制了技术路径的分化</strong></li></ul><h3 id="反事实2-如果openai不准备ipo" tabindex="-1">反事实2：如果OpenAI不准备IPO <a class="header-anchor" href="#反事实2-如果openai不准备ipo" aria-label="Permalink to &quot;反事实2：如果OpenAI不准备IPO&quot;">​</a></h3><ul><li>Altman不会改口&quot;员工更划算&quot;</li><li>&quot;AI取代就业&quot;的叙事会继续传播</li><li>监管压力会更大</li><li><strong>结论：IPO是叙事的分水岭——从&quot;颠覆者&quot;变成&quot;合作者&quot;</strong></li></ul><h3 id="反事实3-如果ai音频也烧钱" tabindex="-1">反事实3：如果AI音频也烧钱 <a class="header-anchor" href="#反事实3-如果ai音频也烧钱" aria-label="Permalink to &quot;反事实3：如果AI音频也烧钱&quot;">​</a></h3><ul><li>整个AI行业的叙事会截然不同</li><li>&quot;AI商业化&quot;会变成&quot;下一个核聚变&quot;——永远差5年</li><li>资本会更快撤离</li><li><strong>结论：AI音频的盈利不仅是商业成功——它是整个AI行业的&quot;可行性证明&quot;</strong></li></ul><h3 id="反事实4-如果j-space没有被发现" tabindex="-1">反事实4：如果J-space没有被发现 <a class="header-anchor" href="#反事实4-如果j-space没有被发现" aria-label="Permalink to &quot;反事实4：如果J-space没有被发现&quot;">​</a></h3><ul><li>AI安全仍然聚焦在输出对齐</li><li>CoT安全漏洞不会被发现——因为没有人去看推理过程</li><li>15个推理模型的防线会继续存在——但只是&quot;纸面上的安全&quot;</li><li><strong>结论：J-space不是&quot;有趣&quot;的发现——它是AI安全从&quot;表面&quot;到&quot;内部&quot;的转折点</strong></li></ul><hr><h2 id="八、扩展层-未来推演-2026-2028" tabindex="-1">八、扩展层：未来推演（2026-2028） <a class="header-anchor" href="#八、扩展层-未来推演-2026-2028" aria-label="Permalink to &quot;八、扩展层：未来推演（2026-2028）&quot;">​</a></h2><h3 id="_2026-h2-分化加速" tabindex="-1">2026 H2：分化加速 <a class="header-anchor" href="#_2026-h2-分化加速" aria-label="Permalink to &quot;2026 H2：分化加速&quot;">​</a></h3><ul><li>ElevenLabs估值突破$50B → AI音频成为&quot;AI商业化的标杆&quot;</li><li>AI视频仍然烧钱 → 第一个盈利的AI视频公司出现（可能在中国）</li><li>第一个AI Agent拿到千万级订单 → 从&quot;demo&quot;到&quot;production&quot;的壁垒被打破</li><li>OpenAI IPO → 市值$200B+，但首日破发 &gt; 泡沫信号</li></ul><h3 id="_2027-泡沫破裂或软着陆" tabindex="-1">2027：泡沫破裂或软着陆 <a class="header-anchor" href="#_2027-泡沫破裂或软着陆" aria-label="Permalink to &quot;2027：泡沫破裂或软着陆&quot;">​</a></h3><ul><li><strong>泡沫破裂情景</strong>：AI资本回报率低于预期 → 资本撤离 → 大量AI公司倒闭</li><li><strong>软着陆情景</strong>：AI商业化逐渐兑现 → 资本开支合理化 → 真正的AI巨头浮现</li><li>历史经验：2000年互联网泡沫破裂后，Google和Amazon成为巨头。2027年谁会成为AI时代的Google？</li></ul><h3 id="_2028-后泡沫时代" tabindex="-1">2028：后泡沫时代 <a class="header-anchor" href="#_2028-后泡沫时代" aria-label="Permalink to &quot;2028：后泡沫时代&quot;">​</a></h3><ul><li>幸存者：拥有护城河（数据、网络效应、硬件）的AI公司</li><li>淘汰者：纯&quot;AI wrapper&quot;——没有护城河，只有API调用</li><li>新范式：AI从&quot;工具&quot;变成&quot;基础设施&quot;——像电力一样，无处不在但不再被讨论</li></ul><h3 id="关键不确定性" tabindex="-1">关键不确定性 <a class="header-anchor" href="#关键不确定性" aria-label="Permalink to &quot;关键不确定性&quot;">​</a></h3><ol><li><strong>AGI时间表</strong>：如果2028年出现AGI，以上推演全部作废</li><li><strong>监管</strong>：EU AI Act的执行力度 vs 美国/中国的监管路径</li><li><strong>地缘政治</strong>：台海、芯片禁运、技术脱钩——任何一个都可能改变所有推演</li></ol>',85)])])}const A=a(e,[["render",r]]);export{c as __pageData,A as default};
